mapper.select:
INSERT INTO food_item (
    food_name
  , storage_type
  , category
  , quantity_text
  , expired_at
  , purchased_at
  , opened_at
  , frozen_at
  , source_type
  , freeze_type
  , status
  , memo
  , created_at
  , updated_at
  , capacity_text
  , source_memo
  , sell_by_at
) VALUES (
    #{foodName}
  , #{storageType}
  , #{category}
  , #{quantityText}
  , #{expiredAt,jdbcType=DATE}
  , #{purchasedAt,jdbcType=DATE}
  , #{openedAt,jdbcType=DATE}
  , #{frozenAt,jdbcType=DATE}
  , #{sourceType}
  , #{freezeType}
  , #{status}
  , #{memo}
  , #{createdAt}
  , #{updatedAt}
  , #{capacityText,jdbcType=VARCHAR}
  , #{sourceMemo,jdbcType=VARCHAR}
  , #{sellByAt,jdbcType=DATE}
)
RETURNING food_id

INSERT INTO food_history (
    food_id
  , action_type
  , previous_storage_type
  , new_storage_type
  , quantity_text
  , memo
) VALUES (
    #{foodId}
  , #{action}
  , #{previous,jdbcType=VARCHAR}
  , #{next,jdbcType=VARCHAR}
  , '1끼'
  , '행동 메모'
)
RETURNING history_id
